  function begin(){window.dispatchEvent(new Event('game-started'));keepAwake(true);if(settings.autoFullscreen&&device()!=='pc')enterFullscreen();epoch++;pendingPacket=null;inFlight=0;actionFlying=false;pred.on=false;pred.hist.clear();appliedSeq=0;needFull=true;queue=[];retryAt=0;playing=true;panel=null;lastDialog='';lastBiome=-1;lastEvent=world.eventId||0;$('overlay').classList.add('hidden');$('home').classList.add('hidden');$('hud').classList.remove('hidden');document.body.classList.add('playing');$('connection').textContent=online?connectionLabel():'AVENTURA SOLO';A.resetCamera(p());A.portrait($('hud-portrait'),p().classId,p().appearance||'female',p().look);drawIcons();$('world').focus();hud();if(p()?.arenaActive)setTimeout(()=>window.ArenaUI?.open(),0);toast('Bem-vindo ao vale. Converse com Íria na praça, ao norte.');}
  let wardrobeDraft=null;
