    if(b.dataset.appearance){selectedAppearance=b.dataset.appearance;if(customLook){customLook={...customLook,body:selectedAppearance==='male'?'man':'woman'};const box=$('creation-tailor');if(box&&!box.classList.contains('hidden'))window.WorldCustomizer.mount(box,customLook,selectedClass,selectedAppearance,look=>{customLook=look;});}document.querySelectorAll('[data-appearance]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.appearance===selectedAppearance)));classPreview();return;}
    if(b.dataset.changeAppearance){command('appearance',{value:b.dataset.changeAppearance});setTimeout(()=>A.portrait($('hud-portrait'),p().classId,p().appearance,p().look),60);close();return;}
    if(b.dataset.class){selectedClass=b.dataset.class;document.querySelectorAll('[data-class]').forEach(x=>{x.classList.toggle('selected',x.dataset.class===selectedClass);x.setAttribute('aria-pressed',String(x.dataset.class===selectedClass));});classPreview();return;}
