    const P=pad.pressed,H=pad.held,g=pad.glyphs,B=padBinding,dx=(H('right')?1:0)-(H('left')?1:0),dy=(H('down')?1:0)-(H('up')?1:0),x=pad.move.x||dx,y=pad.move.y||dy;
